#define SOURCE_REST_PLAN_FIXTURE_ONLY
#include "source-rest-plan.cpp"
#include "dome/gltf-export.hpp"
#include "gltf-document.hpp"
#include "cgltf.h"
namespace {
Vec3 transform(const float *m,Vec3 p){return {m[0]*p.x+m[4]*p.y+m[8]*p.z+m[12],m[1]*p.x+m[5]*p.y+m[9]*p.z+m[13],m[2]*p.x+m[6]*p.y+m[10]*p.z+m[14]};}
Vec3 consume(cgltf_node &node,size_t vertex){auto &primitive=node.mesh->primitives[0];float q[4]{};if(!cgltf_accessor_read_float(cgltf_find_accessor(&primitive,cgltf_attribute_type_position,0),vertex,q,3))throw std::runtime_error("Independent POSITION read failed");Vec3 position{q[0],q[1],q[2]};for(size_t target=0;target<primitive.targets_count;++target){const auto weight=target<node.weights_count?node.weights[target]:target<node.mesh->weights_count?node.mesh->weights[target]:0;for(size_t a=0;a<primitive.targets[target].attributes_count;++a)if(primitive.targets[target].attributes[a].type==cgltf_attribute_type_position){if(!cgltf_accessor_read_float(primitive.targets[target].attributes[a].data,vertex,q,3))throw std::runtime_error("Independent morph read failed");position+=Vec3{q[0],q[1],q[2]}*weight;}}
 if(!node.skin){float world[16];cgltf_node_transform_world(&node,world);return transform(world,position);}Vec3 result{};float sum=0;for(int set=0;;++set){const auto *joints=cgltf_find_accessor(&primitive,cgltf_attribute_type_joints,set),*weights=cgltf_find_accessor(&primitive,cgltf_attribute_type_weights,set);if(!joints&&!weights)break;if(!joints||!weights)throw std::runtime_error("Unpaired independent skin stream");float js[4],ws[4];if(!cgltf_accessor_read_float(joints,vertex,js,4)||!cgltf_accessor_read_float(weights,vertex,ws,4))throw std::runtime_error("Independent skin read failed");for(size_t k=0;k<4;++k)if(ws[k]){if(js[k]<0||js[k]>=node.skin->joints_count)throw std::runtime_error("Independent skin joint out of range");float world[16],bind[16];cgltf_node_transform_world(node.skin->joints[size_t(js[k])],world);if(!node.skin->inverse_bind_matrices||!cgltf_accessor_read_float(node.skin->inverse_bind_matrices,size_t(js[k]),bind,16))throw std::runtime_error("Independent explicit IBM missing");result+=transform(world,transform(bind,position))*ws[k];sum+=ws[k];}}
 if(std::abs(sum-1)>1e-5)throw std::runtime_error("Independent exported weight sum differs");return result;
}
void verify(const Scene &scene,const std::filesystem::path &file){const auto bytes=scene.encode();auto surfaces=scene.surfaces();auto output=detail::make_gltf(surfaces);const auto identities=output.objects;detail::write_glb(std::move(output),file);cgltf_data *raw=nullptr;cgltf_options options{};if(cgltf_parse_file(&options,file.c_str(),&raw)!=cgltf_result_success)throw std::runtime_error("Independent parser refused native source-rest GLB");std::unique_ptr<cgltf_data,decltype(&cgltf_free)> owner(raw,cgltf_free);check(cgltf_load_buffers(&options,raw,file.c_str())==cgltf_result_success&&cgltf_validate(raw)==cgltf_result_success,"Independent cgltf validates actual source-rest hierarchy/attributes/skin accessors");size_t corners=0,rigids=0,skins=0;double worst=0;
 for(size_t part=0;part<surfaces.size();++part){const auto &surface=surfaces[part];auto &node=raw->nodes[identities.at(part).node];if(node.mesh->primitives_count!=1)throw std::runtime_error("Unexpected emitted primitive layout");const auto &primitive=node.mesh->primitives[0];if(!primitive.indices||primitive.indices->count!=surface.mesh.indices.size())throw std::runtime_error("Ordered original corners were lost");const auto evaluated=surface.deformation?surface.deformation->preview(surface.mesh):surface.mesh;const auto world=surface.world_matrix();if(node.skin){++skins;if(node.skin->joints_count!=surface.deformation->skeleton->bones.size())throw std::runtime_error("Export changed actual skin/helper slot count");}else{++rigids;if(surface.deformation&&surface.deformation->skin)throw std::runtime_error("Export dropped a source skin");}
  for(size_t corner=0;corner<surface.mesh.indices.size();++corner){const auto v=surface.mesh.indices[corner];const auto emitted=cgltf_accessor_read_index(primitive.indices,corner);float position[3];if(!cgltf_accessor_read_float(cgltf_find_accessor(&primitive,cgltf_attribute_type_position,0),emitted,position,3))throw std::runtime_error("Independent ordered corner read failed");const auto p=surface.mesh.positions[v];if(position[0]!=p.x||position[1]!=p.y||position[2]!=p.z)throw std::runtime_error("Independent ordered REST corner/position witness differs");const auto point=evaluated.positions[v];const auto expected=world.point({point.x,point.y,point.z});const auto actual=consume(node,emitted);const double error=length(actual-Vec3{float(expected[0]),float(expected[1]),float(expected[2])});worst=std::max(worst,error);if(error>2e-5)throw std::runtime_error("Independent posed/morph/world/IBM source corner mismatch: "+std::to_string(error));++corners;}
 }
 check(skins==19&&rigids==3&&corners>10000,"All real19skins plus3 rigid source instances retain exact corner identity, current morph/pose and each own emitted IBM products");check(scene.encode()==bytes,"Actual export retains exact native source/paint/morph/rig authoring state");std::cout<<file.filename().string()<<" corners="<<corners<<" world_max="<<worst<<'\n';}
}
int main(int argc,char **argv)try{
 if(argc!=3)return 2;const auto directory=std::filesystem::path(argv[2]);std::filesystem::create_directories(directory);const auto placed=directory/"source-placed.vrm",input=directory/"source-rigid.vrm";vrm_source_fixture::source_variant(argv[1],placed,2);vrm_source_fixture::with_rigid_accessories(placed,input);ImportAuthoringOptions options;options.paint_resolution=64;auto imported=prepare_authoring_import(Scene{},input,options);auto scene=imported.scene;const auto selected=imported.objects.front();RigEdit initial;initial.joint=JointAdjustment{scene.object(selected).deformation->humanoid->joints.at("head"),{0,0,17},{}};edit_rig(scene,selected,initial);bool morph=false;for(const auto &o:scene.objects())if(o.deformation&&o.deformation->morphs&&!o.deformation->morphs->targets.empty()){RigEdit change;change.morph=MorphWeightEdit{0,.35f};edit_rig(scene,o.id,change);morph=true;break;}check(morph,"Actual source consumer fixture includes a real authored morph channel");const auto &source=scene.object(selected);RigRestJointEdit fit;fit.joint=initial.joint->joint;const auto point=(scene.world_matrix(selected)*AffineTransform(source.deformation->skeleton->world()[fit.joint])).point({0,0,0});fit.world_position=Vec3{float(point[0]+.005),float(point[1]-.002),float(point[2]+.001)};author_rig_rest(scene,selected,{&fit,1});verify(scene,directory/"source-rest-fitted.glb");RigEdit pose;pose.joint=JointAdjustment{fit.joint,{0,11,0},{.001f,0,0}};edit_rig(scene,selected,pose);verify(scene,directory/"source-rest-posed.glb");restore_rig_source(scene,selected);verify(scene,directory/"source-rest-restored.glb");std::cout<<checks<<" independent actual source REST GLB checks passed\n";return 0;
}catch(const std::exception &error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
